L47: let id = 0;
L48: function rpc(ws, method, params = {}) {
L49:   const msgId = ++id;
L50:   return new Promise((resolve, reject) => {
L51:     const on = (ev) => {
L52:       const m = JSON.parse(ev.data);
L53:       if (m.id !== msgId) return;
L54:       ws.removeEventListener("message", on);
L55:       if (m.error) reject(new Error(method + ": " + m.error.message));
L56:       else resolve(m.result);
L57:     };
L58:     ws.addEventListener("message", on);
L59:     ws.send(JSON.stringify({ id: msgId, method, params }));
L60:   });
L61: }
