L63: // The evaluate helper runs in the page and returns JSON. An async expression
L64: // must return its own JSON string: wrapping a promise in JSON.stringify here
L65: // would stringify the promise, not its value.
L66: const evaluate = (ws, expression, isAsync = false) =>
L67:   rpc(ws, "Runtime.evaluate", {
L68:     expression: isAsync ? expression : `JSON.stringify(${expression})`,
L69:     awaitPromise: true,
L70:     returnByValue: true,
L71:   }).then((r) => (r.result.value ? JSON.parse(r.result.value) : null));
