L55: // Only a blip is worth a second try. A refusal is not: the browser has
L56: // already logged it, and asking again only logs it a second time. 429 is
L57: // excluded on purpose, since asking a rate limited relay again immediately
L58: // makes it worse.
L59: const transient = (e: unknown): boolean => {
L60:   const m = (e instanceof Error && e.message) || "";
L61:   return /^HTTP 5\d\d/.test(m) || /abort|timeout/i.test(m);
L62: };
