L64: async function ask(url: string, ms: number): Promise<string> {
L65:   const ctl = new AbortController();
L66:   const timer = setTimeout(() => ctl.abort(), ms);
L67:   try {
L68:     const r = await fetch(url, { signal: ctl.signal, cache: "no-store" });
L69:     if (!r.ok) {
L70:       // A 404 on the local route means the server in front has no read proxy,
L71:       // which is what `astro dev` answers. Saying so beats reporting "HTTP 404"
L72:       // and leaving the reader to guess which server they are on.
L73:       if (r.status === 404 && url.startsWith("api/raw")) {
L74:         throw new Error("this server has no read proxy");
L75:       }
L76:       throw new Error("HTTP " + r.status);
L77:     }
L78:     const body = await r.text();
L79:     if (body.length < 800) throw new Error("short reply");
L80:     return body;
L81:   } finally {
L82:     clearTimeout(timer);
L83:   }
L84: }
